import { afterEach, beforeAll, describe, expect, test } from 'bun:test';

import * as h from './harness';

beforeAll(h.build);
afterEach(h.clean);

let lock = (...entries: [string, string, string[]?][]) => [
	'# This file is automatically @generated by Cargo.',
	'version = 4',
	...entries.map(([name, version, deps]) => [
		'',
		'[[package]]',
		`name = "${name}"`,
		`version = "${version}"`,
		...deps ? ['dependencies = [', ...deps.map(dep => ` "${dep}",`), ']'] : [],
	].join('\n')),
	'',
].join('\n');

describe('napi layout', () => {
	test('a group keeps the JS wrapper, the crate, and the binaries in lockstep', () => {
		let r = h.repo({
			'bump.json': JSON.stringify({
				independent: true,
				packages: ['.', 'npm/*', 'packages/*'],
				groups: { fast: ['@acme/fast', 'acme-fast', '@acme/fast-darwin-arm64', '@acme/fast-linux-x64-gnu'] },
			}),
			'package.json': h.manifest('@acme/fast', '1.2.0', { optionalDependencies: { '@acme/fast-darwin-arm64': '1.2.0', '@acme/fast-linux-x64-gnu': '1.2.0' } }),
			'Cargo.toml': h.crate('acme-fast', '1.2.0', '[lib]\ncrate-type = ["cdylib"]'),
			'Cargo.lock': lock(['acme-fast', '1.2.0']),
			'src/lib.rs': '',
			'npm/darwin-arm64/package.json': h.manifest('@acme/fast-darwin-arm64', '1.2.0'),
			'npm/linux-x64-gnu/package.json': h.manifest('@acme/fast-linux-x64-gnu', '1.2.0'),
			'packages/cli/package.json': h.manifest('@acme/cli', '0.4.1', { dependencies: { '@acme/fast': '^1.2.0' } }),
		});
		h.tag(r, 'fast@1.2.0');
		h.tag(r, '@acme/cli@0.4.1');
		h.commit(r, { 'src/lib.rs': '// change' });

		let run = h.bump(r, 'minor');
		expect(run.code).toBe(0);
		expect(run.stdout.split('\n').slice(0, 4)).toEqual([
			'~> fast 1.2.0 → 1.3.0 (changed)',
			'     @acme/fast-darwin-arm64, @acme/fast-linux-x64-gnu, @acme/fast, acme-fast',
			'~> @acme/cli 0.4.1 → 0.4.2 (dependent)',
			'~> @acme/fast optionalDependencies["@acme/fast-darwin-arm64"]: 1.2.0 → 1.3.0',
		]);
		expect(h.read(r, 'Cargo.toml')).toContain('version = "1.3.0"');
		expect(h.read(r, 'Cargo.lock')).toBe(lock(['acme-fast', '1.3.0']));
		expect(h.version(r, 'npm/linux-x64-gnu')).toBe('1.3.0');
		expect(JSON.parse(h.read(r, 'packages/cli/package.json')).dependencies).toEqual({ '@acme/fast': '^1.3.0' });
		expect(h.git(r, 'log', '-1', '--format=%s')).toBe('release: fast@1.3.0, @acme/cli@0.4.2');
		expect(h.git(r, 'show', '--name-only', '--format=', 'HEAD').split('\n').sort()).toEqual([
			'Cargo.lock',
			'Cargo.toml',
			'npm/darwin-arm64/package.json',
			'npm/linux-x64-gnu/package.json',
			'package.json',
			'packages/cli/package.json',
		]);
	});
});

describe('cargo workspaces', () => {
	let workspace = (rest: Record<string, string>, root = '[workspace]\nmembers = ["crates/*"]\n\n[workspace.package]\nversion = "1.0.0"\n') => h.repo({
		'Cargo.toml': root,
		...rest,
	});

	test('lockstep releases inherited versions in the workspace root, with its dependencies and lockfile', () => {
		let r = workspace({
			'crates/core/Cargo.toml': h.crate('core', '{ workspace = true }'),
			'crates/app/Cargo.toml': h.crate('app', '{ workspace = true }', [
				'[dependencies]',
				'core = { workspace = true }',
				'',
				"[target.'cfg(unix)'.dependencies]",
				'renamed = { package = "core", path = "../core", version = "1.0" }',
				'',
				'[dev-dependencies.core]',
				'path = "../core"',
				'version = "=1.0.0"',
			].join('\n')),
			'Cargo.lock': lock(['app', '1.0.0', ['core 1.0.0', 'serde']], ['core', '1.0.0'], ['serde', '1.0.0']),
		}, [
			'[workspace]',
			'members = ["crates/*"]',
			'',
			'[workspace.package]',
			'version = "1.0.0" # shared',
			'',
			'[workspace.dependencies]',
			'core = { path = "crates/core", version = "1.0.0" }',
			'',
		].join('\n'));
		h.tag(r, 'v1.0.0');
		h.commit(r, { 'crates/core/src/lib.rs': '' });

		let run = h.bump(r, 'minor', '--json');
		expect(run.code).toBe(0);
		expect(h.read(r, 'Cargo.toml')).toContain('version = "1.1.0" # shared');
		expect(h.read(r, 'Cargo.toml')).toContain('core = { path = "crates/core", version = "1.1.0" }');
		expect(h.read(r, 'crates/app/Cargo.toml')).toContain('renamed = { package = "core", path = "../core", version = "1.1" }');
		expect(h.read(r, 'crates/app/Cargo.toml')).toContain('version = "=1.1.0"');
		expect(h.read(r, 'Cargo.lock')).toBe(lock(['app', '1.1.0', ['core 1.1.0', 'serde']], ['core', '1.1.0'], ['serde', '1.0.0']));

		let result = JSON.parse(run.stdout);
		expect(result.ranges).toEqual([
			{ file: 'Cargo.toml', package: null, dependency: 'core', field: 'workspace.dependencies', from: '1.0.0', to: '1.1.0' },
			{ file: 'crates/app/Cargo.toml', package: 'app', dependency: 'core', field: 'dev-dependencies', from: '=1.0.0', to: '=1.1.0' },
			{ file: 'crates/app/Cargo.toml', package: 'app', dependency: 'core', field: "target.'cfg(unix)'.dependencies", from: '1.0', to: '1.1' },
		]);
		expect(result.units[0].packages.map((pkg: { name: string }) => pkg.name)).toEqual(['core', 'app']);
	});

	test('an untracked lockfile is left alone', () => {
		let r = workspace({ 'crates/a/Cargo.toml': h.crate('a', '1.0.0'), '.gitignore': '.home\nCargo.lock\n' }, '[workspace]\nmembers = ["crates/*"]\n');
		h.tag(r, 'v1.0.0');
		h.write(r, { 'Cargo.lock': lock(['a', '1.0.0']) });
		h.commit(r, { 'crates/a/src/lib.rs': '' });
		expect(h.bump(r, 'patch').code).toBe(0);
		expect(h.read(r, 'Cargo.lock')).toBe(lock(['a', '1.0.0']));
	});

	test('in independent mode, shared versions join an explicit group', () => {
		let r = workspace({
			'bump.json': JSON.stringify({ independent: true, packages: ['crates/*'], groups: { kit: ['a'] } }),
			'crates/a/Cargo.toml': h.crate('a', '{ workspace = true }'),
			'crates/b/Cargo.toml': h.crate('b', '{ workspace = true }'),
			'crates/c/Cargo.toml': h.crate('c', '2.0.0'),
		});
		h.tag(r, 'kit@1.0.0');
		h.tag(r, 'c@2.0.0');
		h.commit(r, { 'crates/b/src/lib.rs': '' });
		let run = h.bump(r, 'patch');
		expect(run.code).toBe(0);
		expect(run.stdout).toStartWith('~> kit 1.0.0 → 1.0.1 (changed)\n     a, b\n');
	});

	test('in independent mode, shared versions take the name of the root crate', () => {
		let r = h.repo({
			'bump.json': JSON.stringify({ independent: true }),
			'Cargo.toml': '[package]\nname = "tool"\nversion.workspace = true\n\n[workspace]\nmembers = ["crates/*"]\n\n[workspace.package]\nversion = "1.0.0"\n',
			'crates/a/Cargo.toml': h.crate('a', '{ workspace = true }'),
		});
		h.tag(r, 'tool@1.0.0');
		h.commit(r, { 'crates/a/src/lib.rs': '' });
		let run = h.bump(r, 'patch');
		expect(run.code).toBe(0);
		expect(run.stdout).toStartWith('~> tool 1.0.0 → 1.0.1 (changed)\n     a, tool\n');
	});

	test('in independent mode, shared versions without a name are an error, unless only one crate shares it', () => {
		let r = workspace({
			'bump.json': JSON.stringify({ independent: true, packages: ['crates/*'] }),
			'crates/a/Cargo.toml': h.crate('a', '{ workspace = true }'),
			'crates/b/Cargo.toml': h.crate('b', '{ workspace = true }'),
		});
		expect(h.bump(r, 'patch').stderr).toBe('error: Crates "a", "b" share [workspace.package] version; name them in "groups", e.g. "groups": { "<name>": ["a"] }\n');

		h.commit(r, { 'crates/b/Cargo.toml': h.crate('b', '3.0.0') });
		h.tag(r, 'a@1.0.0');
		h.tag(r, 'b@3.0.0');
		h.commit(r, { 'crates/a/src/lib.rs': '' });
		expect(h.bump(r, 'patch').code).toBe(0);
		expect(h.read(r, 'Cargo.toml')).toContain('version = "1.0.1"');
	});

	test('discovers path dependencies as members, and honors exclude', () => {
		let r = h.repo({
			'Cargo.toml': '[workspace]\nmembers = ["app"]\nexclude = ["vendor"]\n',
			'app/Cargo.toml': h.crate('app', '1.0.0', '[dependencies]\nhelper = { path = "../helper", version = "1.0.0" }\nold = { path = "../vendor/old" }'),
			'helper/Cargo.toml': h.crate('helper', '1.0.0'),
			'vendor/old/Cargo.toml': h.crate('old', '9.0.0'),
		});
		h.tag(r, 'v1.0.0');
		h.commit(r, { 'helper/src/lib.rs': '' });
		let run = h.bump(r, 'patch');
		expect(run.code).toBe(0);
		expect(run.stdout).toStartWith('~> 1.0.0 → 1.0.1 (changed)\n     helper, app\n');
		expect(h.read(r, 'vendor/old/Cargo.toml')).toContain('version = "9.0.0"');
	});

	test('reads each publish form', () => {
		let r = h.repo({
			'Cargo.toml': '[workspace]\nmembers = ["crates/*"]\n\n[workspace.package]\npublish = false\n',
			'crates/a/Cargo.toml': h.crate('a', '1.0.0', 'publish = false'),
			'crates/b/Cargo.toml': h.crate('b', '1.0.0', 'publish = []'),
			'crates/c/Cargo.toml': h.crate('c', '1.0.0', 'publish.workspace = true'),
			'crates/d/Cargo.toml': h.crate('d', '1.0.0', 'publish = ["corp"]'),
		});
		let result = JSON.parse(h.bump(r, 'patch', '--all', '--adopt', '--json', '--dryrun').stdout);
		expect(result.units[0].packages.map((pkg: { name: string; publish: boolean }) => [pkg.name, pkg.publish])).toEqual([['a', false], ['b', false], ['c', false], ['d', true]]);
	});
});
